	if cmd.Args[0] != "pi" {
		t.Fatalf("Args[0] = %q, want pi; args=%v", cmd.Args[0], cmd.Args)
	}
	wantPrefix := []string{"pi", "--mode", "json", "--print", "--append-system-prompt", review.ReviewerGuardrail, "--model", "anthropic/claude-sonnet-4-5:high"}
